import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, float, mix, uniform, mx_noise_float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-2-bg';

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.RepeatWrapping;
  map.wrapT = THREE.RepeatWrapping;

  const inkColor = uniform(new THREE.Color(0x16161d));
  const surfaceColor = uniform(new THREE.Color(0x0b0b10));
  const accentColor = uniform(new THREE.Color(0xff2a38));

  const uvNode = uv();
  const texSample = texture(map, uvNode);

  // engineered gradient: vertical blend between surface and ink
  const gradientMix = uvNode.y.clamp(0.0, 1.0);
  const gradient = mix(surfaceColor, inkColor, gradientMix);

  // subtle grain via noise
  const grain = mx_noise_float(uvNode.mul(512.0)).mul(0.03);

  // thin accent edge line near top of card
  const edgeLine = uvNode.y.smoothstep(0.96, 0.985).sub(uvNode.y.smoothstep(0.985, 1.0));
  const withAccent = mix(gradient, accentColor, edgeLine.mul(0.6));

  const combined = withAccent.add(vec3(grain, grain, grain)).mul(texSample.rgb.mul(0.85).add(0.15));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = vec4(combined, 1.0);
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-card-2-bg-mesh';
  group.add(mesh);

  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
